package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.copyCurrentStructure.
 * Target: Maximize branch and line coverage.
 */
public class TokenBuffer_copyCurrentStructure_TriageGen0Test {

    private ObjectMapper mapper;
    private JsonFactory factory;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        factory = mapper.getFactory();
    }

    /**
     * Test simple value types (default case in switch).
     */
    @Test
    public void testCopyCurrentStructure_SimpleValue() throws IOException {
        String json = "\"hello\"";
        TokenBuffer tb = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to VALUE_STRING
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("\"hello\"", sw.toString());
    }

    /**
     * Test START_OBJECT structure.
     */
    @Test
    public void testCopyCurrentStructure_StartObject() throws IOException {
        String json = "{\"key\":\"value\"}";
        TokenBuffer tb = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to START_OBJECT
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("{\"key\":\"value\"}", sw.toString());
    }

    /**
     * Test START_ARRAY structure.
     */
    @Test
    public void testCopyCurrentStructure_StartArray() throws IOException {
        String json = "[1, 2, 3]";
        TokenBuffer tb = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to START_ARRAY
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("[1,2,3]", sw.toString());
    }

    /**
     * Test FIELD_NAME handling (the first if block).
     * This tests the logic where t == FIELD_NAME, then it calls writeFieldName and moves to next token.
     */
    @Test
    public void testCopyCurrentStructure_FieldName() throws IOException {
        String json = "{\"field\":\"value\"}";
        TokenBuffer tb = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        // The structure should contain the field name and the value
        assertEquals("{\"field\":\"value\"}", sw.toString());
    }

    /**
     * Test nested structures (recursion).
     */
    @Test
    public void testCopyCurrentStructure_Nested() throws IOException {
        String json = "{\"a\":[{\"b\":1}]}";
        TokenBuffer tb = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("{\"a\":[{\"b\":1}]}", sw.toString());
    }

    /**
     * Test with _mayHaveNativeIds = true.
     * This triggers the _checkNativeIds calls in both the FIELD_NAME block and the main block.
     */
    @Test
    public void testCopyCurrentStructure_WithNativeIds_FieldName() throws IOException {
        // Using the constructor that sets hasNativeIds to true
        TokenBuffer tb = new TokenBuffer(mapper, true);
        String json = "{\"id\":\"123\"}";

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        // Since we don't have a custom implementation of _checkNativeIds in this mock context,
        // we just ensure it doesn't crash and performs the standard copy.
        assertEquals("{\"id\":\"123\"}", sw.toString());
    }

    /**
     * Test with _mayHaveNativeIds = true and a simple value.
     */
    @Test
    public void testCopyCurrentStructure_WithNativeIds_SimpleValue() throws IOException {
        TokenBuffer tb = new TokenBuffer(mapper, true);
        String json = "true";
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // VALUE_TRUE
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("true", sw.toString());
    }

    /**
     * Test edge case: null value.
     */
    @Test
    public void testCopyCurrentStructure_Null() throws IOException {
        String json = "null";
        TokenBuffer tb = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // VALUE_NULL
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("null", sw.toString());
    }
}
